async function fnLoadFactoryInteriorModel(url) {
    //const position = { x: 1200, z: 1200 };
    const position = new THREE.Vector3(1200, getHeight(1200, 1200), 1200)
    const name = 'factory_interior';
    let mesh, material, diffuseMap, model, colliderMesh, colliderBVH, collisionRadius;


    model = await modelLoader.loadModel(url);


    mesh = model.children[0];
    const LOD1 = model.children[0].clone();

    diffuseMap = mesh.material.map;

    mesh.castShadow = true;
    mesh.receiveShadow = true;

    // Transform children locally (no position - that goes on LOD)
    mesh.rotateY((-Math.PI / 2));
    mesh.scale.set(9.98, 9.98, 9.98);

    LOD1.rotateY((-Math.PI / 2));
    LOD1.scale.set(9.98, 9.98, 9.98);

    // Basic red material for LOD1 testing
    LOD1.material = new THREE.MeshStandardMaterial({
        map: mesh.material.map,  // Get map directly from original
        envMap: worldScene.envMap,
        envMapIntensity: 1.5
    });

    //create LOD - position goes HERE, not on children
    const lod = new THREE.LOD();
    lod.position.set(position.x, position.y, position.z);
    lod.addLevel(mesh, 0);         // projection material when close (0-400 units)
    lod.addLevel(LOD1, 900);       // red basic material when far (400+ units)



    //colliderMesh = model.children[1];
    material = fnCreateVideoMaterial();

    mesh.material = material;

    // Update shader uniforms
    const videoTest = document.createElement('video');
    videoTest.src = './assets/glass/super8.webm';
    videoTest.loop = true;
    videoTest.muted = true; // Important for autoplay
    videoTest.crossOrigin = 'anonymous';
    videoTest.play();

    // Create a video texture
    const videoTextureTest = new THREE.VideoTexture(videoTest);
    videoTextureTest.minFilter = THREE.LinearFilter;
    videoTextureTest.magFilter = THREE.LinearFilter;
    videoTextureTest.format = THREE.RGBAFormat;

    // Create a larger target surface
    const surfaceWidth = 75;  // Larger width
    //const surfaceHeight = surfaceWidth * (9 / 16);// Larger height
    const surfaceHeight = surfaceWidth * (3 / 4);// Larger height

    // Define the projection area relative to the surface size
    // These values control the relative size and position of the projection on the surface
    const projectionParams = {
        // Size of projection as a fraction of the surface dimensions
        relativeWidth: 0.5,    // 50% of surface width
        relativeHeight: 0.5,   // 60% of surface height
        // Center position of projection (0,0 is center, values from -0.5 to 0.5)
        offsetX: 0.0,         // Offset to the left
        offsetY: -0.25           // Offset slightly upward
    };

    const targetCenter = new THREE.Vector3(
        projectionParams.offsetX * surfaceWidth,
        projectionParams.offsetY * surfaceHeight,
        0
    );

    // Create the projector object (this will be the source of projection)
    const projector = new THREE.Object3D();

    projector.position.set(
        projectionParams.offsetX * surfaceWidth - 650,  // Center X over target
        getHeight(1200, 1200) + 20,                     // Position high above
        710   // Center Z over target
    );

    //projector.rotation.set(0, -Math.PI / 2, 0);  // -90 degrees on X axis

    projector.lookAt(
        projectionParams.offsetX * surfaceWidth + 50,
        projectionParams.offsetY * surfaceHeight,
        0
    ); // Point at the center of the desired projection area

    worldScene.scene.add(projector);

    //projector.position.set(0, 0, 0);




    //soundManager.play('projector');

    const projectorAudioSource = new THREE.Object3D();
    projectorAudioSource.position.set(1250, getHeight(1250, 1200) + PERSON_HEIGHT, 1200);
    worldScene.scene.add(projectorAudioSource);
    //soundManager.loadPositionalSound('projector', './assets/sounds/projector2.mp3', projectorAudioSource, 60.0);


    soundSources.set(projectorAudioSource.id, { audioSource: projectorAudioSource, type: 'projector', name: 'projector', path: './assets/sounds/projector2.mp3', isPlaying: false });


    // Get the static projector position and direction
    const projectorPosition = new THREE.Vector3();
    projector.getWorldPosition(projectorPosition);

    const projectorDirection = new THREE.Vector3();
    projector.getWorldDirection(projectorDirection);
    projectorDirection.negate(); // Flip to point forward

    // Create a static view matrix for the projector
    const projectorViewMatrix = new THREE.Matrix4();
    projectorViewMatrix.lookAt(
        projectorPosition,
        new THREE.Vector3().addVectors(projectorPosition, projectorDirection),
        new THREE.Vector3(0, 1, 0)
    );

    // Calculate field of view to cover only a portion of the surface
    // We'll use a narrower FOV to restrict the projection area
    const distance = projectorPosition.distanceTo(targetCenter);
    const targetWidth = surfaceWidth * projectionParams.relativeWidth;
    const targetHeight = surfaceHeight * projectionParams.relativeHeight;

    // Calculate FOV based on the desired projection width and distance
    const fovX = 2 * Math.atan(targetWidth / (2 * distance));
    const fovY = 2 * Math.atan(targetHeight / (2 * distance));
    const fov = Math.max(fovX, fovY); // Use the larger angle to ensure coverage
    const aspect = targetWidth / targetHeight;

    const projectorProjectionMatrix = new THREE.Matrix4();
    projectorProjectionMatrix.makePerspective(-aspect * Math.tan(fov / 2), aspect * Math.tan(fov / 2), Math.tan(fov / 2), -Math.tan(fov / 2), 1, 1000);

    // Combine into one static projector matrix
    const projectorMatrix = new THREE.Matrix4().multiplyMatrices(
        projectorProjectionMatrix,
        projectorViewMatrix
    );

    material.uniforms.uProjectorPosition.value = projectorPosition;
    material.uniforms.uProjectorDirection.value = projectorDirection;
    material.uniforms.uProjectorMatrix.value = projectorMatrix;
    material.uniforms.uDiffuseMap.value = diffuseMap;
    material.uniforms.uVideoTexture.value = videoTextureTest;
    material.uniforms.uMinZDistance.value = (position.z + 500); //500
    material.uniforms.uTerrainHeight.value = getHeight(1200, 1200);
    material.uniforms.uFadeHeight.value = 2.5;

    material.envMap = worldScene.envMap;
    material.envMapIntensity = 2.10;




    Utils.fnAddModelToRegistry(modelRegistry, name, mesh, position, diffuseMap, true, true, 700, false, colliderBVH, collisionRadius);
    worldScene.scene.add(lod)

}

