// Animation state
const cameraAnimationState = {
    startTime: null,
    isAnimating: false, // Flag to control animation
    duration: 5000,
    fnCheckOrientationCanRun: false
};

// Easing function (Ease In-Out Quad)
function easeInOutQuad(t) {
    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

function fnAnimateCamera() {
    // Time management
    const currentTime = performance.now();
    if (cameraAnimationState.isAnimating) {
        if (!cameraAnimationState.startTime) {
            cameraAnimationState.startTime = currentTime;
        }

        const elapsed = currentTime - cameraAnimationState.startTime;
        let progress = Math.min(elapsed / cameraAnimationState.duration, 1); // Clamp progress between 0 and 1
        // Apply easing function to progress
        progress = easeInOutQuad(progress);

        // Interpolate position
        const interpolatedPosition = new THREE.Vector3().lerpVectors(startPosition, endPosition, progress);

        // Calculate dynamic y position
        const dynamicY = getHeight(interpolatedPosition.x, interpolatedPosition.z) + PERSON_HEIGHT;


        // Set camera position
        camera.position.set(interpolatedPosition.x, dynamicY, interpolatedPosition.z);


        // Stop animation when completed
        if (progress >= 1) {
            cameraAnimationState.isAnimating = false;
            cameraAnimationState.fnCheckOrientationCanRun = true;
            if (!visitedFromMobileDevice) {
                document.querySelector('.wasd-icon').classList.remove('hide');
            }

        }
    }
}

